properties.query:
let windowSize = 1h;

// S100: Swarm Saturation (전역 게이트 — UAVFleetState_CL엔 Operator 없음, FleetId 기준)
let SwarmSatTime = toscalar(
    UAVFleetState_CL
    | where TimeGenerated > ago(windowSize)
    | where AnomalyScore > 0.7 or DivergingCount > 2 or UnknownUavIdDetected == true
    | summarize min(TimeGenerated));
// S90: SOC LLM Prompt Injection (제안 스키마 — AI/ML 추론계층 전용 테이블 미배포, UAVOpAudit_CL을 EventType 판별자로 대리 사용)
let S90 =
    UAVOpAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType in ('llm_injection_detected','prompt_injection','soc_llm_anomaly') or FailReason has 'injection'
    | project TimeGenerated, Operator;
S90
| where isnotnull(SwarmSatTime) and TimeGenerated <= SwarmSatTime and TimeGenerated >= SwarmSatTime - windowSize
| extend CampaignType = "C9_SOC_LLM인젝션_군집포화"
| extend StepSummary = strcat("S90@", tostring(TimeGenerated), " → S100(전역/FleetId기준)@", tostring(SwarmSatTime))
| extend Severity = "High"
| project TimeGenerated, SwarmSatTime, Operator, CampaignType, StepSummary, Severity
